using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class WorkProgressionTests
{
    static readonly EntityId Issuer=new("person:shingen");
    internal static ContractWorld New(bool progress=true){var d=TransportWorkTests.New().NewGame!;return NewGameWorld.Create(d.Start,d.Registered,d.Selected.Value,42,NewGameWorld.CompactPersonalAuthority,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:progress?WorkProgression.Policy:NewGameWork.Policy);}
    static void At(WorldSession s,long t)=>NewGameWorldTests.At(s,t);
    static WorldSession Report(bool progress=true){var s=new WorldSession(New(progress));Assert.Equal(ResultCode.Accepted,s.Submit(NewGameWorld.LocalWork(s.DiagnosticSnapshot(),"request:merit"),s.Revision).Code);At(s,1);foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())s.Open(s.PlayerControl,m.Id,s.Revision);var t=s.DiagnosticSnapshot().Tasks.Last();if(t.Kind==TaskKind.VoluntaryRequest)s.Assent(t.Id,s.PlayerControl,true,s.Revision);At(s,8);return s;}
    static EntityId Open(WorldSession s){var note=AssessmentNotice.Inbox(s,s.PlayerControl).Single();Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,note.Message,s.Revision).Code);return note.Message;}
    [Fact]public void UnopenedAssessmentDoesNotRevealPromotionOfNextPrivateJob(){var s=Report();Assert.Equal(0,WorkProgression.Recognized(s.DiagnosticSnapshot(),Issuer));Assert.Equal(100,TransportWork.OfferAt(s.DiagnosticSnapshot(),new("job:before-read"))!.Amount);Open(s);Assert.Equal(1,WorkProgression.Recognized(s.DiagnosticSnapshot(),Issuer));Assert.Equal(200,TransportWork.OfferAt(s.DiagnosticSnapshot(),new("job:after-read"))!.Amount);Assert.Equal(30,TransportWork.OfferAt(s.DiagnosticSnapshot(),new("job:after-read"))!.Fee);}
    [Fact]public void ReopeningDoesNotAccumulateMerit(){var s=Report();var id=Open(s);Assert.Equal(ResultCode.AlreadyAccepted,s.Open(s.PlayerControl,id,s.Revision).Code);Assert.Equal(1,WorkProgression.Recognized(s.DiagnosticSnapshot(),Issuer));}
    [Fact]public void RecognitionIsSpecificToIssuer(){var s=Report();Open(s);Assert.Equal(0,WorkProgression.Recognized(s.DiagnosticSnapshot(),new("person:nobunaga")));}
    [Fact]public void OldProfileRetainsReceiptAndOldJobAmounts(){var s=Report(false);Open(s);Assert.Equal("点検完了の申告を受領",AssessmentNotice.LatestKnown(s,s.PlayerControl).Single().Review.Achievement);Assert.Equal(0,WorkProgression.Recognized(s.DiagnosticSnapshot(),Issuer));Assert.Equal(100,TransportWork.OfferAt(s.DiagnosticSnapshot(),new("job:old"))!.Amount);}
    [Fact]public void RecognitionDoesNotChangeOfficeOrAllocateMilitaryRights(){var s=Report();var before=s.DiagnosticSnapshot();Open(s);var after=s.DiagnosticSnapshot();Assert.Equal(ContractJson.Write(before.Grants),ContractJson.Write(after.Grants));Assert.Equal(ContractJson.Write(before.Offices),ContractJson.Write(after.Offices));Assert.Null(after.NewMilitary);Assert.Equal(WorkProgression.Achievement,AssessmentNotice.LatestKnown(s,s.PlayerControl).Single().Review.Achievement);}
    [Fact]public void NewContractFreezesBiggerAmountAndRetainsRealStockConservation(){var s=Report();Open(s);var id=new EntityId("job:earned");Assert.Equal(ResultCode.Accepted,s.RequestTransport(id,s.Revision).Code);var j=TransportWork.Jobs(s.DiagnosticSnapshot()).Single();Assert.Equal(200,j.Handover.Terms.Amount);var op=new EntityId("operation:earned-accept");Assert.Equal(ResultCode.Accepted,s.HandoverTransport(id,new(op,HandoverAction.Accept,s.PlayerControl,j.Handover.Terms.Source,Issuer,null,s.Seconds,0),s.Revision).Code);op=new("operation:earned-collect");Assert.Equal(ResultCode.Accepted,s.HandoverTransport(id,new(op,HandoverAction.Collect,s.PlayerControl,j.Handover.Terms.Source,Issuer,new("transfer:transport/"+op.Value.Replace(':','/')),s.Seconds,1),s.Revision).Code);Assert.Equal(200,s.DiagnosticSnapshot().ResourceLots.Single(l=>l.Id==TransportWork.Cargo(id)).Quantity);Assert.Equal(800,NewGameWork.Balance(s.DiagnosticSnapshot(),Issuer));}
    [Fact]public void OldOriginalDoesNotGainAmountFromLaterAssessment(){var s=new WorldSession(New());var id=new EntityId("job:fixed-before-assessment");s.RequestTransport(id,s.Revision);Assert.Equal(100,TransportWork.Jobs(s.DiagnosticSnapshot()).Single().Handover.Terms.Amount);s.Submit(NewGameWorld.LocalWork(s.DiagnosticSnapshot(),"request:later-merit"),s.Revision);At(s,1);foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())s.Open(s.PlayerControl,m.Id,s.Revision);At(s,8);Open(s);Assert.Equal(100,TransportWork.Jobs(s.DiagnosticSnapshot()).Single().Handover.Terms.Amount);_ =new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));}
    [Fact]public void GenerationRestorePreservesKnownEvaluationAndNextOffer(){var s=Report();Open(s);s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"progression-"+Guid.NewGuid().ToString("N")),w.Definitions);store.Save(s,"manual",w.WorldId,new(0,1));var host=new WorldSessionHost(new(New()));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("manual"),host.Current,host.Current.Revision));Assert.Equal(1,WorkProgression.Recognized(host.Current.DiagnosticSnapshot(),Issuer));Assert.Equal(ContractJson.Write(TransportWork.OfferAt(w,new("job:next"))),ContractJson.Write(TransportWork.OfferAt(host.Current.DiagnosticSnapshot(),new("job:next"))));Assert.Equal(ContractJson.CanonicalHash(w),ContractJson.CanonicalHash(host.Current.DiagnosticSnapshot()));}
}
